jsonTools.init:
function init(eli) {
  var OVERLAY_ID = "_eli3_tour_root";
  var Z = 100000;
  var _active = false;
  var _idx = 0;
  var _els = {};
  var _dragPos = null;      // per-step drag offset (reset each stop)
  var _onResize = null;
  var _onKey = null;
  var _onDocClick = null;
  var _relayoutTimer = null;
  var _dlgObserver = null;
  // When the user clicks the highlighted element (e.g. Settings), drop the
  // dim/spotlight so whatever opens is fully usable. The mascot card stays so
  // they can keep going. Reset on each step change.
  var _spotPaused = false;
  var _targetEl = null;
  var _targetClick = null;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function _q(sel) { try { return document.querySelector(sel); } catch (_e) { return null; } }
  function _mascot() {
    try { if (eli.ui && typeof eli.ui.mascot === "function") return eli.ui.mascot(); } catch (_e) {}
    return '<div style="font-size:30px;line-height:1;">🤖</div>';
  }
  // Best-effort: find a small visible element under `container` whose title
  // or text matches `re` (for the footer data-upload control, which is a
  // tool-registered slot with no fixed class).
  function _byText(container, re) {
    if (!container) return null;
    var nodes = container.querySelectorAll("*");
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      if (!n.offsetParent || n.children.length > 5) continue;
      var t = ((n.getAttribute && (n.getAttribute("title") || n.getAttribute("aria-label") || "")) + " " + (n.textContent || ""));
      if (re.test(t)) return n;
    }
    return null;
  }
  function _closeUnpinned() {
    try {
      var m = _q("#_eli3_unpinned_menu");
      if (m) { var c = _q("._eli3_unpinned_close"); if (c) c.click(); else m.remove(); }
    } catch (_e) {}
  }

  // ─── Tour script ──────────────────────────────────────────────────────
  // dim:false → no backdrop/ring (reserved for steps shown over a dialog).
  var STEPS = [
    { title: "Welcome — Home base",
      body: "Hi, I'm ELI 👋 Let me show you around. This is your Home button — tap it any time to come straight back to this dashboard from anywhere in ELI. (You can drag me out of the way whenever you like.)",
      target: function () { return _q(".beta-home-btn"); } },
    { title: "Help & support",
      body: "Click the ELI logo any time for Help, to contact support or report a bug, and to view the console. It's your safety net if you ever get stuck — go ahead, give it a click.",
      target: function () { return _q(".app-label") || _q(".brand-titles") || _q(".brand-group"); } },
    { title: "Settings",
      body: "Your control center — language, AI model, theme, and admin options all live behind this cog.",
      target: function () { return _q("#btnHeaderSettings"); } },
    { title: "The status bar",
      body: "Along the bottom is a row of quick utilities. Let's look at three of them.",
      target: function () { return _q("._eli3_status_bar"); } },
    { title: "Version & updates",
      body: "Down here on the right is your version pill — it shows what you're on and flags when a new version is ready.",
      target: function () { return _q("._eli3_footer_slot_right") || _q("._eli3_status_bar"); } },
    { title: "Zoom",
      body: "Make the panel bigger or smaller to fit your screen — especially handy on a laptop.",
      target: function () { return _q("._eli3_status_zoom") || _q("._eli3_status_zoom_btn") || _q("._eli3_status_bar"); } },
    { title: "OARS data",
      body: "This is your OARS data — the intake details for the request. It's usually uploaded automatically for you, and we'll cover it in more depth in Phase 2.",
      target: function () { return _q("._eli3_footer_slot_left") || _q("._eli3_status_bar"); } },
    { title: "Your toolbar",
      body: "This side rail shows the type of document you're working on, your usage stats, and — down at the bottom — your trophy box.",
      target: function () { return _q("#_eli3_sidebar"); } },
    { title: "Your tools",
      body: "Every tool you've pinned shows up here as a tile — just click one to launch it.",
      target: function () { return _q("#_eli3_dashboard_main"); } },
    { title: "Session feed",
      body: "Everything you do this session is saved here. Click the loaded-document entry for a quick summary of the doc, and click any tool you've used to jump right back in and pick up where you left off.",
      target: function () { return _q("#_eli3_activity_panel") || _q("#_eli3_activity_rail"); } },
    { title: "Ask ELI",
      body: "Right here at the top is Ask ELI — your AI assistant. Attach a document or an EI template, save a custom question you use often, or hit Improve to sharpen your prompt. Go ahead and ask ELI to summarize the document.",
      target: function () { return _q("._eli3_home_ask") || _q("._eli3_home_ask_box") || _q("#_eli3_dashboard_main"); } },
    { title: "More tools & customize",
      body: "Click the + to open every tool you haven't pinned — run any of them without cluttering your dashboard, and use Customize to pin, unpin, and reorder your tiles. Go ahead and try it. That's the tour — enjoy ELI!",
      target: function () { return _q("#_eli3_add_btn_wrap"); } },
  ];

  // ─── Overlay DOM ──────────────────────────────────────────────────────
  function _ensureDom() {
    _teardownDom();
    var root = document.createElement("div");
    root.id = OVERLAY_ID;
    ["t", "b", "l", "r"].forEach(function (k) {
      var d = document.createElement("div");
      d.className = "_eli3_tour_dim";
      root.appendChild(d); _els["dim_" + k] = d;
    });
    var ring = document.createElement("div");
    ring.className = "_eli3_tour_ring";
    root.appendChild(ring); _els.ring = ring;
    var card = document.createElement("div");
    card.className = "_eli3_tour_card";
    root.appendChild(card); _els.card = card;
    document.body.appendChild(root); _els.root = root;
  }
  function _teardownDom() {
    var ex = document.getElementById(OVERLAY_ID);
    if (ex) ex.remove();
    _els = {};
  }
  function _setRect(el, x, y, w, h) {
    el.style.left = Math.round(x) + "px"; el.style.top = Math.round(y) + "px";
    el.style.width = Math.max(0, Math.round(w)) + "px"; el.style.height = Math.max(0, Math.round(h)) + "px";
  }
  function _hideSpot() {
    ["dim_t", "dim_b", "dim_l", "dim_r"].forEach(function (k) { if (_els[k]) _els[k].style.display = "none"; });
    if (_els.ring) _els.ring.style.display = "none";
  }
  function _showSpot(r) {
    var vw = window.innerWidth, vh = window.innerHeight, p = 6;
    var x = Math.max(0, r.left - p), y = Math.max(0, r.top - p);
    var w = Math.min(vw, r.width + p * 2), h = Math.min(vh, r.height + p * 2);
    if (x + w > vw) w = vw - x; if (y + h > vh) h = vh - y;
    ["dim_t", "dim_b", "dim_l", "dim_r"].forEach(function (k) { _els[k].style.display = "block"; });
    _setRect(_els.dim_t, 0, 0, vw, y);
    _setRect(_els.dim_b, 0, y + h, vw, vh - (y + h));
    _setRect(_els.dim_l, 0, y, x, h);
    _setRect(_els.dim_r, x + w, y, vw - (x + w), h);
    _els.ring.style.display = "block";
    _setRect(_els.ring, x, y, w, h);
  }
  function _placeCard(r) {
    var card = _els.card;
    var prevVis = card.style.visibility;
    card.style.visibility = "hidden"; card.style.left = "-9999px"; card.style.top = "0px";
    var cw = card.offsetWidth, ch = card.offsetHeight, m = 14;
    var vw = window.innerWidth, vh = window.innerHeight;
    var pos = null;
    if (_dragPos) {
      pos = { x: _dragPos.x, y: _dragPos.y };
    } else if (r) {
      var clampY = function (yy) { return Math.max(m, Math.min(vh - ch - m, yy)); };
      var clampX = function (xx) { return Math.max(m, Math.min(vw - cw - m, xx)); };
      var cands = [
        { x: r.right + m, y: clampY(r.top) },             // right
        { x: r.left - cw - m, y: clampY(r.top) },         // left
        { x: clampX(r.left), y: r.bottom + m },           // below
        { x: clampX(r.left), y: r.top - ch - m },         // above
      ];
      for (var i = 0; i < cands.length; i++) {
        var c = cands[i];
        if (c.x >= m && c.y >= m && c.x + cw <= vw - m && c.y + ch <= vh - m) { pos = c; break; }
      }
    }
    if (!pos) pos = { x: (vw - cw) / 2, y: vh - ch - m * 2 };
    pos.x = Math.max(m, Math.min(vw - cw - m, pos.x));
    pos.y = Math.max(m, Math.min(vh - ch - m, pos.y));
    card.style.left = Math.round(pos.x) + "px"; card.style.top = Math.round(pos.y) + "px";
    card.style.visibility = prevVis || "";
  }

  function _dots() {
    var out = "";
    for (var i = 0; i < STEPS.length; i++) {
      out += '<span class="_eli3_tour_dot' + (i === _idx ? " _on" : "") + '"></span>';
    }
    return out;
  }
  function _renderCard(step) {
    var last = _idx === STEPS.length - 1;
    var card = _els.card;
    card.innerHTML =
      '<div class="_eli3_tour_accent"></div>' +
      '<div class="_eli3_tour_hd">' +
        '<div class="_eli3_tour_av">' + _mascot() + '</div>' +
        '<div class="_eli3_tour_idwrap"><span class="_eli3_tour_name">ELI</span>' +
          '<span class="_eli3_tour_sub">Guided tour</span></div>' +
        '<button type="button" class="_eli3_tour_x" title="End tour">✕</button>' +
      '</div>' +
      '<div class="_eli3_tour_body">' +
        '<div class="_eli3_tour_title">' + _esc(step.title) + '</div>' +
        '<div class="_eli3_tour_txt">' + _esc(step.body) + '</div>' +
      '</div>' +
      '<div class="_eli3_tour_ft">' +
        '<div class="_eli3_tour_dots">' + _dots() + '</div>' +
        '<div class="_eli3_tour_btns">' +
          (_idx > 0 ? '<button type="button" class="_eli3_tour_back">Back</button>' : '') +
          '<button type="button" class="_eli3_tour_next">' + (last ? "Finish" : "Next →") + '</button>' +
        '</div>' +
      '</div>';
    card.querySelector("._eli3_tour_x").onclick = _end;
    card.querySelector("._eli3_tour_next").onclick = function () { last ? _end() : _go(_idx + 1); };
    var backBtn = card.querySelector("._eli3_tour_back");
    if (backBtn) backBtn.onclick = function () { _go(_idx - 1); };
    _wireDrag(card.querySelector("._eli3_tour_hd"));
  }

  function _wireDrag(handle) {
    if (!handle) return;
    handle.addEventListener("mousedown", function (ev) {
      if (ev.button !== 0 || ev.target.closest("._eli3_tour_x")) return;
      var card = _els.card, rect = card.getBoundingClientRect();
      var sx = ev.clientX, sy = ev.clientY, ol = rect.left, ot = rect.top, moved = false;
      function mv(e) {
        var dx = e.clientX - sx, dy = e.clientY - sy;
        if (!moved && Math.abs(dx) + Math.abs(dy) < 3) return;
        moved = true;
        var w = card.offsetWidth, h = card.offsetHeight;
        var nl = Math.max(6, Math.min(window.innerWidth - w - 6, ol + dx));
        var nt = Math.max(6, Math.min(window.innerHeight - h - 6, ot + dy));
        card.style.left = nl + "px"; card.style.top = nt + "px";
        _dragPos = { x: nl, y: nt };
      }
      function up() { document.removeEventListener("mousemove", mv); document.removeEventListener("mouseup", up); }
      document.addEventListener("mousemove", mv); document.addEventListener("mouseup", up);
      ev.preventDefault();
    });
  }

  // Drop the click listener from the previous step's target.
  function _detachTarget() {
    if (_targetEl && _targetClick) {
      try { _targetEl.removeEventListener("click", _targetClick); } catch (_e) {}
    }
    _targetEl = null; _targetClick = null;
  }

  function _renderStep(step) {
    _renderCard(step);
    // Expand to full size BEFORE _placeCard measures — otherwise a leftover
    // collapsed (_min) card from a prior Settings click is measured short,
    // placed near the bottom, then grows past the footer / off-screen.
    _els.card.classList.remove("_min");
    var tgt = null;
    try { tgt = step.target ? step.target() : null; } catch (_e) {}
    if (step.dim === false || !tgt || _spotPaused) {
      _hideSpot();
      _placeCard(tgt ? tgt.getBoundingClientRect() : null);
    } else {
      try { tgt.scrollIntoView({ block: "center", inline: "nearest" }); } catch (_e) {}
      var r = tgt.getBoundingClientRect();
      _showSpot(r);
      _placeCard(r);
    }
    // Clicking the highlighted element drops the dim so the user can freely
    // explore what it opens (Settings panel, etc.); the card stays for Next.
    _detachTarget();
    if (tgt && step.dim !== false) {
      _targetEl = tgt;
      // Clicking the target: drop the dim AND collapse the card to just its
      // header + Back/Next, so the opened panel (Settings, etc.) is unobscured.
      _targetClick = function () {
        _spotPaused = true; _hideSpot();
        if (_els.card) _els.card.classList.add("_min");
      };
      try { tgt.addEventListener("click", _targetClick); } catch (_e) {}
    }
    _els.card.classList.remove("_in", "_min"); void _els.card.offsetWidth; _els.card.classList.add("_in");
  }

  // Navigate to step i, running the prior step's after() then the new
  // step's before() so menu/dialog state is correct in both directions.
  function _go(i) {
    if (!_active) return;
    i = Math.max(0, Math.min(STEPS.length - 1, i));
    var prev = STEPS[_idx];
    var leaving = (i !== _idx) ? prev : null;
    var wasPaused = _spotPaused; // user clicked into something (e.g. Settings)
    _dragPos = null;
    _spotPaused = false;
    _detachTarget();
    var p = Promise.resolve();
    // Safety net: if we're not currently on the dashboard — you opened
    // Settings, launched a tool, etc. — Next returns home FIRST so the next
    // stop's target exists. _eli3_dashboard_main is only present on the
    // dashboard; tool/settings views replace it. goHome is the kernel's
    // full home reset (there is no eli.dashboard.render).
    var notHome = !document.getElementById("_eli3_dashboard_main");
    if ((wasPaused || notHome) && eli.dashboard && typeof eli.dashboard.goHome === "function") {
      p = p.then(function () { try { eli.dashboard.goHome(); } catch (_e) {} return _wait(300); });
    }
    if (leaving && leaving.after) p = p.then(function () { return leaving.after(); });
    _idx = i;
    var step = STEPS[_idx];
    p.then(function () { return step.before ? step.before() : null; })
     .then(function () { if (_active) _renderStep(step); })
     .catch(function () { if (_active) _renderStep(step); });
  }

  // Re-resolve the current target and re-wrap it. The tour is interactive —
  // users click highlighted elements, which open menus / shift layout, so the
  // spotlight tracks the live position. If the target navigated away (e.g. a
  // tile launched a tool), hide the spotlight so nothing is obscured. The
  // card is NOT repositioned here (respects drag + avoids jitter).
  // Hide the entire tour while a kernel dialog (.eli-overlay) OR the unpinned
  // apps menu is open, so those show ABOVE the tour and the spotlight ring
  // isn't drawn over the "+" you just clicked. Checked doc-wide because the
  // unpinned menu attaches to the "+" wrap, not <body>.
  function _syncOverlayVisibility() {
    if (!_active || !_els.root) return;
    var blocking = document.querySelector(".eli-overlay")
      || document.getElementById("_eli3_unpinned_menu")
      || document.getElementById("_agls_backdrop"); // Agreement at a Glance slide-up
    _els.root.style.visibility = blocking ? "hidden" : "";
  }

  function _relayoutCurrent() {
    if (!_active) return;
    _syncOverlayVisibility();
    if (_spotPaused) return;
    var step = STEPS[_idx];
    if (!step || step.dim === false) return;
    var tgt = null;
    try { tgt = step.target ? step.target() : null; } catch (_e) {}
    if (!tgt) { _hideSpot(); return; }
    var r = tgt.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) { _hideSpot(); return; }
    _showSpot(r);
  }

  function _bind() {
    _onResize = function () { if (_active) _renderStep(STEPS[_idx]); };
    window.addEventListener("resize", _onResize);
    _relayoutTimer = setInterval(_relayoutCurrent, 400);
    // Step fully aside whenever a kernel dialog (.eli-overlay) is open — the
    // ELI AI Help/Contact dialog, etc. — so it's never obscured by the tour,
    // independent of z-index. Restore when the dialog closes.
    if (typeof MutationObserver === "function") {
      _dlgObserver = new MutationObserver(function () { _syncOverlayVisibility(); });
      try { _dlgObserver.observe(document.body, { childList: true, subtree: true }); } catch (_e) {}
    }
    _onKey = function (e) {
      if (!_active) return;
      if (e.key === "Escape") { _end(); }
      else if (e.key === "ArrowRight") { if (_idx < STEPS.length - 1) _go(_idx + 1); }
      else if (e.key === "ArrowLeft") { if (_idx > 0) _go(_idx - 1); }
    };
    document.addEventListener("keydown", _onKey, true);
    // The Home button is the universal escape: clicking it any time during
    // the tour exits the tour (the kernel's own handler still takes you home).
    // Capture phase so it fires even though the dim sits visually on top.
    _onDocClick = function (e) {
      if (!_active || !e.target || !e.target.closest) return;
      // Skip the very first stop, where Home IS the highlighted element being
      // demoed (clicking it there just pauses/explores, doesn't exit).
      if (_idx === 0) return;
      if (e.target.closest(".beta-home-btn")) _end();
    };
    document.addEventListener("click", _onDocClick, true);
  }
  function _unbind() {
    if (_onResize) window.removeEventListener("resize", _onResize);
    if (_onKey) document.removeEventListener("keydown", _onKey, true);
    if (_onDocClick) document.removeEventListener("click", _onDocClick, true);
    if (_relayoutTimer) { clearInterval(_relayoutTimer); _relayoutTimer = null; }
    if (_dlgObserver) { try { _dlgObserver.disconnect(); } catch (_e) {} _dlgObserver = null; }
    _onResize = _onKey = _onDocClick = null;
  }

  function _end() {
    if (!_active) return;
    _active = false;
    _spotPaused = false;
    _detachTarget();
    _closeUnpinned();
    _unbind();
    if (_els.card) { _els.card.classList.add("_out"); }
    setTimeout(_teardownDom, 180);
    try { eli.log.event("tool", "dashboard_tour_ended", { atStep: _idx }); } catch (_e) {}
  }

  function _startTour() {
    if (_active) return;
    _active = true;
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTour"); } catch (_e) {}
    var pre = (eli.dashboard && typeof eli.dashboard.goHome === "function") ? Promise.resolve(eli.dashboard.goHome()) : Promise.resolve();
    Promise.resolve(pre).then(function () { return _wait(220); }).then(function () {
      if (!_active) return;
      _ensureDom(); _bind();
      _idx = 0;
      var s = STEPS[0];
      return (s.before ? Promise.resolve(s.before()) : Promise.resolve()).then(function () {
        if (_active) _renderStep(s);
      });
    }).catch(function () { if (_active && _els.card) _renderStep(STEPS[0]); });
  }

  // No tile — the tour is launched only via this channel (Demo Director
  // Phase 1 dispatches eli.dispatch("tour", "start")).
  eli.register({
    tour: { start: function () { _startTour(); } },
  });
}

jsonTools.css:
/* dashboard_tour — premium guided tour overlay. Navy/gold to match the
   ELI dashboard chrome. Sized for laptops (compact card). */

/* z below kernel dialogs (9999+) so the Help/Contact, Settings, and Customize
   dialogs the tour invites you to open render ABOVE the spotlight. Still well
   above dashboard chrome. */
#_eli3_tour_root { position: fixed; inset: 0; z-index: 9500; pointer-events: none; }

/* Dimming panels around the spotlight (four rects leave the target fully
   uncovered). pointer-events:none so the dim is purely visual — clicks pass
   through to whatever is under it, so the Home button (and the rest of the
   chrome) stays reachable at every step. The tour is fully interactive. */
._eli3_tour_dim {
  position: fixed; background: rgba(13, 27, 42, 0.62); pointer-events: none;
  backdrop-filter: blur(0.5px); transition: opacity 0.2s ease;
}

/* Gold spotlight ring */
._eli3_tour_ring {
  position: fixed; pointer-events: none; border-radius: 12px;
  border: 2px solid #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.22), 0 0 22px 4px rgba(201, 162, 39, 0.45);
  z-index: 100002;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1),
              width 0.28s cubic-bezier(0.4, 0, 0.2, 1), height 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  animation: _eli3_tour_pulse 2s ease-in-out infinite;
}
@keyframes _eli3_tour_pulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.20), 0 0 18px 3px rgba(201, 162, 39, 0.38); }
  50%      { box-shadow: 0 0 0 4px rgba(201, 162, 39, 0.30), 0 0 26px 6px rgba(201, 162, 39, 0.55); }
}

/* The mascot speech card */
._eli3_tour_card {
  position: fixed; z-index: 100010; pointer-events: auto;
  width: min(300px, 88vw); box-sizing: border-box;
  background: linear-gradient(160deg, #0d1b2a 0%, #1b263b 100%);
  border: 1px solid rgba(201, 162, 39, 0.55); border-radius: 14px;
  box-shadow: 0 18px 50px rgba(13, 27, 42, 0.55), 0 2px 0 rgba(255, 255, 255, 0.04) inset;
  color: #e2e8f0; overflow: hidden;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}
._eli3_tour_card._in { animation: _eli3_tour_cardin 0.26s cubic-bezier(0.34, 1.4, 0.5, 1); }
._eli3_tour_card._out { opacity: 0; transform: scale(0.97); transition: opacity 0.16s ease, transform 0.16s ease; }
@keyframes _eli3_tour_cardin {
  0% { opacity: 0; transform: translateY(6px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

._eli3_tour_accent {
  height: 3px; width: 100%;
  background: linear-gradient(90deg, #b8901f 0%, #f2d866 50%, #b8901f 100%);
}

._eli3_tour_hd {
  display: flex; align-items: center; gap: 10px; padding: 11px 12px 9px; cursor: move;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07); user-select: none;
}
._eli3_tour_av {
  flex: 0 0 auto; width: 40px; height: 40px; border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #16263c, #0b1626);
  border: 1.5px solid #c9a227; box-shadow: 0 0 14px rgba(201, 162, 39, 0.35);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
._eli3_tour_av svg, ._eli3_tour_av img { width: 88%; height: 88%; display: block; }
._eli3_tour_idwrap { display: flex; flex-direction: column; gap: 1px; flex: 1 1 auto; min-width: 0; }
._eli3_tour_name { font: 800 13px/1 Georgia, 'Book Antiqua', serif; letter-spacing: 0.04em; color: #f2d866; }
._eli3_tour_sub { font: 600 8.5px/1 Inter, sans-serif; letter-spacing: 0.16em; text-transform: uppercase; color: #7c8aa0; }
._eli3_tour_x {
  flex: 0 0 auto; border: none; background: transparent; color: #94a3b8;
  font-size: 14px; line-height: 1; cursor: pointer; padding: 2px 4px; border-radius: 5px;
}
._eli3_tour_x:hover { color: #e2e8f0; background: rgba(255, 255, 255, 0.08); }

/* Collapsed state — shown while the user is exploring a clicked element
   (e.g. Settings). Only the header + Back/Next remain so the panel is clear. */
._eli3_tour_card._min ._eli3_tour_body { display: none; }
._eli3_tour_card._min ._eli3_tour_hd { border-bottom: none; }

._eli3_tour_body { padding: 11px 14px 4px; }
._eli3_tour_title { font: 700 14px/1.25 Georgia, 'Book Antiqua', serif; color: #fff; margin-bottom: 5px; }
._eli3_tour_txt { font: 400 12.5px/1.55 Inter, sans-serif; color: #cbd5e1; }

._eli3_tour_ft {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 10px 14px 13px;
}
._eli3_tour_dots { display: flex; align-items: center; gap: 5px; }
._eli3_tour_dot {
  width: 6px; height: 6px; border-radius: 50%; background: rgba(255, 255, 255, 0.20);
  transition: background 0.2s ease, transform 0.2s ease;
}
._eli3_tour_dot._on { background: #c9a227; transform: scale(1.25); box-shadow: 0 0 8px rgba(201, 162, 39, 0.6); }
._eli3_tour_btns { display: flex; align-items: center; gap: 7px; }

._eli3_tour_back {
  border: 1px solid rgba(255, 255, 255, 0.18); background: rgba(255, 255, 255, 0.06);
  color: #cbd5e1; font: 700 11px/1 Inter, sans-serif; padding: 7px 11px; border-radius: 7px;
  cursor: pointer; transition: background 0.12s ease;
}
._eli3_tour_back:hover { background: rgba(255, 255, 255, 0.13); }
._eli3_tour_next {
  border: 1px solid #b8901f; color: #3a2c05; font: 800 11px/1 Inter, sans-serif;
  padding: 7px 14px; border-radius: 7px; cursor: pointer;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 60%, #b8901f 100%);
  box-shadow: 0 2px 8px rgba(201, 162, 39, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.12s ease, transform 0.12s ease;
}
._eli3_tour_next:hover { filter: brightness(1.06); transform: translateY(-1px); }
._eli3_tour_next:active { transform: translateY(0); }
